(() => {
  const PROJECTS = [
    { id: "tabum", name: "Tabum", category: "AI / NEWS", url: "https://tabum.org" },
    { id: "whitehousewar", name: "White House War", category: "EXPERIMENT / GAME", url: "https://whitehousewar-production.up.railway.app/" },
    { id: "eatsafely", name: "EatSafely", category: "PUBLIC DATA", url: "https://eatsafely.org" },
    { id: "notary", name: "Thurston Mobile Notary", category: "LOCAL SERVICE", url: "https://thurstonnotary.com/" },
    { id: "docuformer", name: "DocuFormer", category: "AI / DOCUMENTS", url: null }
  ];
  const PORTFOLIO_URL = "https://jhilwig.com";
  const css = `
    :host {
      --jh-bg:#111;
      --jh-fg:#f4f2eb;
      --jh-muted:#97958f;
      --jh-line:rgba(255,255,255,.16);
      display:block;
      width:100%;
      color:var(--jh-fg);
      background:var(--jh-bg);
      font-family:"Helvetica Neue",Helvetica,Arial,sans-serif;
      -webkit-font-smoothing:antialiased;
      text-rendering:optimizeLegibility;
    }
    *{box-sizing:border-box}
    .footer{
      border-top:1px solid var(--jh-line);
      background:var(--jh-bg);
      color:var(--jh-fg);
    }
    details{margin:0}
    summary{list-style:none;cursor:pointer;user-select:none}
    summary::-webkit-details-marker{display:none}
    .panel{
      padding:22px 18px 26px;
      border-bottom:1px solid var(--jh-line);
    }
    .panelHead{
      display:flex;
      justify-content:space-between;
      gap:16px;
      margin-bottom:12px;
      font:600 10px/1 ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,"Liberation Mono",monospace;
      letter-spacing:.09em;
      text-transform:uppercase;
    }
    .panelHead a{
      color:inherit;
      text-decoration:none;
      border-bottom:1px solid currentColor;
      padding-bottom:2px;
    }
    .projects{margin:0;padding:0;list-style:none}
    .project,.current,.disabled{
      display:grid;
      grid-template-columns:30px minmax(155px,1.25fr) 1fr auto;
      gap:14px;
      align-items:center;
      min-height:44px;
      border-top:1px solid var(--jh-line);
      color:inherit;
      text-decoration:none;
    }
    .project{transition:padding-left .18s ease}
    .project:hover{padding-left:6px}
    .current .name::after{
      content:" CURRENT";
      margin-left:8px;
      color:var(--jh-muted);
      font:600 9px/1 ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,"Liberation Mono",monospace;
      letter-spacing:.07em;
    }
    .disabled{opacity:.45}
    .num,.category{
      color:var(--jh-muted);
      font:500 10px/1 ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,"Liberation Mono",monospace;
    }
    .category{
      letter-spacing:.075em;
      text-transform:uppercase;
    }
    .name{
      font-size:14px;
      font-weight:590;
      letter-spacing:-.01em;
    }
    .arrow{
      color:var(--jh-muted);
      font:500 12px/1 ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,"Liberation Mono",monospace;
    }
    .bar{
      min-height:43px;
      display:grid;
      grid-template-columns:auto 1fr auto;
      gap:10px;
      align-items:center;
      padding:0 16px;
    }
    .mark{
      width:23px;
      height:23px;
      display:grid;
      place-items:center;
      border:1px solid rgba(255,255,255,.76);
      border-radius:999px;
      font:700 9px/1 ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,"Liberation Mono",monospace;
    }
    .byline,.toggle{
      font:600 10px/1 ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,"Liberation Mono",monospace;
      letter-spacing:.08em;
      text-transform:uppercase;
    }
    .toggle{justify-self:end;white-space:nowrap}
    .mobile{display:none}
    .plus{
      display:inline-block;
      margin-left:5px;
      transition:transform .2s ease;
    }
    details[open] .plus{transform:rotate(45deg)}
    summary:focus-visible,a:focus-visible{
      outline:2px solid #fff;
      outline-offset:-2px;
    }
    .srOnly{
      position:absolute;
      width:1px;
      height:1px;
      padding:0;
      margin:-1px;
      overflow:hidden;
      clip:rect(0,0,0,0);
      white-space:nowrap;
      border:0;
    }
    @media(max-width:700px){
      .panel{padding:18px 14px 22px}
      .project,.current,.disabled{
        grid-template-columns:24px 1fr auto;
        min-height:48px;
        gap:10px;
      }
      .category{display:none}
      .desktop{display:none}
      .mobile{display:inline}
      .bar{min-height:44px;padding:0 12px}
      .panelHead{font-size:9px}
      .name{font-size:13px}
    }
    @media(max-width:390px){
      .byline,.toggle{font-size:9px;letter-spacing:.06em}
      .mark{width:22px;height:22px}
    }
    @media(prefers-reduced-motion:reduce){
      .project,.plus{transition:none}
    }
  `;
  const esc = (value="") => String(value)
    .replaceAll("&","&amp;")
    .replaceAll("<","&lt;")
    .replaceAll(">","&gt;")
    .replaceAll('"',"&quot;")
    .replaceAll("'","&#039;");
  class JHProjectFooter extends HTMLElement {
    constructor(){
      super();
      this.attachShadow({mode:"open"});
    }
    static get observedAttributes(){
      return ["project"];
    }
    connectedCallback(){
      this.render();
    }
    attributeChangedCallback(){
      if(this.isConnected) this.render();
    }
    projectRow(project,index,currentId){
      const number=String(index+1).padStart(2,"0");
      if(project.id===currentId){
        return `<li><div class="current" aria-current="page">
          <span class="num">${number}</span>
          <span class="name">${esc(project.name)}</span>
          <span class="category">${esc(project.category)}</span>
          <span class="arrow">—</span>
        </div></li>`;
      }
      if(!project.url){
        return `<li><div class="disabled" title="URL not configured yet">
          <span class="num">${number}</span>
          <span class="name">${esc(project.name)}</span>
          <span class="category">${esc(project.category)}</span>
          <span class="arrow">—</span>
        </div></li>`;
      }
      return `<li><a class="project" href="${esc(project.url)}" target="_blank" rel="noopener noreferrer">
        <span class="num">${number}</span>
        <span class="name">${esc(project.name)}</span>
        <span class="category">${esc(project.category)}</span>
        <span class="arrow" aria-hidden="true">↗</span>
        <span class="srOnly">Opens in a new tab</span>
      </a></li>`;
    }
    bindOpenBehavior(){
      const details=this.shadowRoot.querySelector("details");
      if(!details) return;
      details.addEventListener("toggle",()=>{
        if(!details.open) return;
        const reduceMotion =
          window.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches;
        requestAnimationFrame(()=>{
          requestAnimationFrame(()=>{
            window.scrollTo({
              top:document.documentElement.scrollHeight,
              behavior:reduceMotion ? "auto" : "smooth"
            });
          });
        });
      });
    }
    render(){
      const currentId=this.getAttribute("project")||"";
      this.shadowRoot.innerHTML=`
        <style>${css}</style>
        <footer class="footer">
          <details>
            <div class="panel">
              <div class="panelHead">
                <span>More projects by Jay Hilwig</span>
                <a href="${PORTFOLIO_URL}" target="_blank" rel="noopener noreferrer">
                  jhilwig.com ↗
                  <span class="srOnly">Opens in a new tab</span>
                </a>
              </div>
              <ul class="projects">
                ${PROJECTS.map((project,index)=>this.projectRow(project,index,currentId)).join("")}
              </ul>
            </div>
            <summary class="bar" aria-label="Show more projects by Jay Hilwig">
              <span class="mark" aria-hidden="true">JH</span>
              <span class="byline">
                <span class="desktop">Designed + built by Jay Hilwig</span>
                <span class="mobile">A Jay Hilwig project</span>
              </span>
              <span class="toggle">
                Projects <span class="plus" aria-hidden="true">+</span>
              </span>
            </summary>
          </details>
        </footer>
      `;
      this.bindOpenBehavior();
    }
  }
  if(!customElements.get("jh-project-footer")){
    customElements.define("jh-project-footer",JHProjectFooter);
  }
})();